import sys

def is_1122_string(s):
    # Check if the length of the string is even
    if len(s) % 2 != 0:
        return "No"

    # Check if each character appears exactly twice
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    for count in char_count.values():
        if count != 2:
            return "No"

    # Check if the string satisfies the 1122 pattern
    for i in range(1, len(s) // 2 + 1):
        if s[2 * i - 2] != s[2 * i - 1]:
            return "No"

    return "Yes"

