from collections import defaultdict

MOD = 998244353

def factorial(n):
    if n == 0:
        return 1
    result = 1
    for i in range(2, n + 1):
        result = (result * i) % MOD
    return result

def inverse_factorial(n):
    return pow(factorial(n), MOD - 2, MOD)

def count_sequences(N, A, B):
    # Count occurrences of each number in A and B
    count_A = [0] * (2 * N + 1)
    count_B = [0] * (2 * N + 1)

    for num in A:
        count_A[num] += 1

    for num in B:
        if num != -1:
            count_B[num] += 1

    # Check if counts are valid
    for i in range(1, 2 * N + 1):
        if count_A[i] > 1 or count_B[i] > 1:
            return 0

    # Calculate the number of valid pairs (a, b)
    valid_pairs = 1
    for i in range(1, 2 * N + 1):
        if count_A[i] == 1 and count_B[i] == 1:
            valid_pairs = (valid_pairs * 2) % MOD

    return valid_pairs

