        n = len(nums)
        prefix_sum = [0] * (n + 1)
        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + nums[i]

        max_sum = float('-inf')
        remainder_map = {0: -1}

        for i in range(1, n + 1):
