    def findMinimumTime(self, strength: List[int], K: int) -> int:
        n = len(strength)
        dp = [[float('inf')] * (K + 1) for _ in range(n + 1)]
        dp[0][0] = 0

        for i in range(1, n + 1):
            for j in range(K + 1):
                # Option 1: Skip the current lock
                if dp[i - 1][j] != float('inf'):
                    dp[i][j] = min(dp[i][j], dp[i - 1][j])

                # Option 2: Break the current lock
                x = 1
                energy = 0
                time = 0
                while energy < strength[i - 1]:
                    energy += x
                    time += 1
                    x += 1

                if j > 0:
                    dp[i][j] = min(dp[i][j], dp[i - 1][j - 1] + time)

        return min(dp[n])
