from typing import List

class Solution:
    def maxAmount(self, initialCurrency: str, pairs1: List[List[str]], rates1: List[float], pairs2: List[List[str]], rates2: List[float]) -> float:
        # Create adjacency lists for both sets of currency pairs
        graph1 = {}
        for i in range(len(pairs1)):
            start, target = pairs1[i]
            if start not in graph1:
                graph1[start] = []
            graph1[start].append((target, rates1[i]))
            if target not in graph1:
                graph1[target] = []
            graph1[target].append((start, 1 / rates1[i]))

        graph2 = {}
        for i in range(len(pairs2)):
            start, target = pairs2[i]
            if start not in graph2:
                graph2[start] = []
            graph2[start].append((target, rates2[i]))
            if target not in graph2:
                graph2[target] = []
            graph2[target].append((start, 1 / rates2[i]))

        # Function to perform DFS and find the maximum amount
        def dfs(graph, start, visited, current_amount):
            visited.add(start)
            max_amount = current_amount
            for neighbor, rate in graph.get(start, []):
                if neighbor not in visited:
                    max_amount = max(max_amount, dfs(graph, neighbor, visited, current_amount * rate))
            visited.remove(start)
            return max_amount

        # Calculate the maximum amount for both days
        max_amount_day1 = dfs(graph1, initialCurrency, set(), 1.0)
        max_amount_day2 = dfs(graph2, initialCurrency, set(), 1.0)

        # Combine the results from both days
        result = 0.0
        for start, target, rate in pairs2:
            if start in graph1:
                result = max(result, max_amount_day1 * rate * graph1[start][graph1[start].index((target, rate))][1])

        return max(max_amount_day1, max_amount_day2, result)
