        from math import gcd
        from functools import reduce

        def lcm(a, b):
            return abs(a*b) // gcd(a, b)

        max_length = 0
        for i in range(len(nums)):
            current_prod = 1
            current_gcd = nums[i]
            current_lcm = nums[i]
            for j in range(i, len(nums)):
                current_prod *= nums[j]
                current_gcd = gcd(current_gcd, nums[j])
                current_lcm = lcm(current_lcm, nums[j])
