import sys
from collections import defaultdict

def read_input():
    input = sys.stdin.read
    data = input().split()

    index = 0
    N = int(data[index])
    M = int(data[index + 1])
    index += 2

    edges = []
    for _ in range(M):
        X = int(data[index]) - 1
        Y = int(data[index + 1]) - 1
        Z = int(data[index + 2])
        edges.append((X, Y, Z))
        index += 3

    return N, M, edges

def find_good_sequence(N, M, edges):
    # Initialize the sequence with zeros
    A = [0] * N

    # Dictionary to store the equations
    equations = defaultdict(list)
    for X, Y, Z in edges:
        equations[X].append((Y, Z))
        equations[Y].append((X, Z))

    # Solve the equations
    visited = set()
    def dfs(node):
        if node in visited:
            return True
        visited.add(node)

        for neighbor, value in equations[node]:
            if A[neighbor] == -1:
                A[neighbor] = A[node] ^ value
            elif A[neighbor] != A[node] ^ value:
                return False

        for neighbor, value in equations[node]:
            if not dfs(neighbor):
                return False

        return True

    for i in range(N):
        if A[i] == -1:
            A[i] = 0
            if not dfs(i):
                return [-1]

    return A

def main():
    N, M, edges = read_input()
    result = find_good_sequence(N, M, edges)
    if result == [-1]:
        print(-1)
    else:
        print(" ".join(map(str, result)))

