def min_front_kicks(H, W, grid, start, end):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < H and 0 <= y < W

    def bfs(start, end):
        queue = deque([start])
        visited = set([start])
        kicks = 0

        while queue:
            size = len(queue)
            for _ in range(size):
                x, y = queue.popleft()

                if (x, y) == end:
                    return kicks

                for dx, dy in directions:
                    nx, ny = x + dx, y + dy

                    if is_valid(nx, ny) and (nx, ny) not in visited:
                        if grid[nx][ny] == '.':
                            visited.add((nx, ny))
                            queue.append((nx, ny))
                        else:
                            # Perform a front kick
                            for kdx in range(-2, 3):
                                for kdy in range(-2, 3):
                                    nxx, nyy = nx + kdx, ny + kdy
                                    if is_valid(nxx, nyy) and grid[nxx][nyy] == '#':
                                        grid[nxx][nyy] = '.'
                            visited.add((nx, ny))
                            queue.append((nx, ny))
                            kicks += 1

        return float('inf')

    return bfs(start, end)

