import heapq

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Build the graph
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))

        # Helper function to check if we can reach all nodes with max_weight
        def can_reach_all(max_weight):
            pq = [(0, 0)]  # (current_max_weight, current_node)
            visited = set()

            while pq:
                current_max_weight, current_node = heapq.heappop(pq)

                if current_node in visited:
                    continue

                visited.add(current_node)

                if len(visited) == n:
                    return True

                for neighbor, weight in graph[current_node]:
                    if weight > max_weight:
                        continue

                    if neighbor not in visited:
                        heapq.heappush(pq, (max(current_max_weight, weight), neighbor))

            return False

        # Binary search for the minimum possible maximum edge weight
        left, right = 1, 10**6
        result = -1

        while left <= right:
            mid = (left + right) // 2

            if can_reach_all(mid) and sum(w for _, w in edges if w <= mid) >= threshold * (threshold - 1) // 2:
                result = mid
                right = mid - 1
            else:
                left = mid + 1

        return result
