        for i in range(n):
            dp[0][i % 2] = cost[i][0] + min(dp[0][(i - 1) % 2], dp[1][(i - 1) % 2])
            dp[1][i % 2] = cost[i][1] + min(dp[0][(i - 1) % 2], dp[1][(i - 1) % 2])
            dp[0][(i + 1) % 2] = cost[i][2] + min(dp[0][(i - 1) % 2], dp[1][(i - 1) % 2])
            dp[1][(i + 1) % 2] = cost[i][2] + min(dp[0][(i - 1) % 2], dp[1][(i - 1) % 2])

        return min(dp[0][(n // 2) % 2], dp[1][(n // 2) % 2]) + min(dp[0][(n // 2 - 1) % 2], dp[1][(n // 2 - 1) % 2])
