class Solution:
    def maxDifference(self, s: str) -> int:
        from collections import Counter

        # Count the frequency of each character in the string
        freq = Counter(s)

        max_diff = 0

        # Iterate through each unique character in the string
        for char in set(s):
            # Get the frequency of the current character
            current_freq = freq[char]

            # Check if the current frequency is odd or even
            if current_freq % 2 == 0:
                # If even, try to find the highest odd frequency
                for other_char in set(s):
                    if other_char != char and freq[other_char] % 2 != 0:
                        max_diff = max(max_diff, freq[other_char] - current_freq)
            else:
                # If odd, try to find the highest even frequency
                for other_char in set(s):
                    if other_char != char and freq[other_char] % 2 == 0:
                        max_diff = max(max_diff, current_freq - freq[other_char])

        return max_diff
