class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)
        prefix_sum = [0] * (n + 1)
        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + points[i]

        def canAchieve(min_val, moves_left):
            left, right = 0, 0
            while right < n:
                if prefix_sum[right + 1] - prefix_sum[left] >= min_val * (right - left + 1):
                    left = right + 1
                else:
                    right += 1
                    moves_left -= 1
                    if moves_left < 0:
                        return False
            return True

        low, high = 0, sum(points) // m
        while low < high:
            mid = (low + high + 1) // 2
            if canAchieve(mid, m):
                low = mid
            else:
                high = mid - 1
        return low
