class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        directions = [(-1, -1), (-1, 1), (1, -1), (1, 1)]

        def is_valid(x, y):
            return 0 <= x < n and 0 <= y < m

        def get_next(x, y, dx, dy):
            if dx == 0:
                return x + dy, y
            elif dy == 0:
                return x, y + dx

        def get_turned_direction(dx, dy):
            if dx == 0:
                return dy, -dx
            else:
                return -dy, dx

        max_length = 0

        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1:
                    for dx, dy in directions:
                        length = 1
                        x, y = i, j
                        while True:
                            nx, ny = get_next(x, y, dx, dy)
                            if not is_valid(nx, ny) or grid[nx][ny] != (2 if length % 2 == 0 else 0):
                                break
                            length += 1
                            x, y = nx, ny

                        # Check for the turned direction
                        ndx, ndy = get_turned_direction(dx, dy)
                        nx, ny = x, y
                        while True:
                            nx, ny = get_next(nx, ny, ndx, ndy)
                            if not is_valid(nx, ny) or grid[nx][ny] != (2 if length % 2 == 0 else 0):
                                break
                            length += 1
                            x, y = nx, ny

                        max_length = max(max_length, length)

        return max_length
