    def maxSum(self, grid: List[List[int]], limits: List[int], k: int) -> int:
        n, m = len(grid), len(grid[0])
        total_elements = sum(limits)

        # If k is greater than or equal to the total number of elements, return the sum of all elements in the grid
        if k >= total_elements:
            return sum(sum(row) for row in grid)

        # Create a list of tuples containing the value and its position
        elements = [(grid[i][j], i, j) for i in range(n) for j in range(m)]
        elements.sort(reverse=True)  # Sort by value in descending order

        selected = []
        used = [0] * n  # Track how many elements have been used from each row

        for val, i, j in elements:
            if used[i] < limits[i]:
                selected.append(val)
                used[i] += 1
                k -= 1
                if k == 0:
                    break

        return sum(selected)
