class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        if k > self.count(n):
            return []

        result = []
        numbers = list(range(1, n + 1))
        parity = 0

        while len(numbers) > 0:
            size = len(numbers)
            block_size = factorial(size - 1)

            if k % 2 == 1:
                if parity == 0:
                    result.append(numbers.pop(0))
                else:
                    result.append(numbers.pop())
            else:
                if parity == 0:
                    result.append(numbers.pop(-1))
                else:
                    result.append(numbers.pop(0))

            k = (k - 1) // block_size if k % 2 == 1 else k // block_size
            parity = 1 - parity

        return result

    def count(self, n: int) -> int:
        if n == 1:
            return 1
        elif n == 2:
            return 2
        else:
            return 2 * factorial(n - 1)
