class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)
        prefix_sum = [0] * (n + 1)
        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + nums[i]

        dp = [[float('inf')] * (k + 1) for _ in range(n)]
        for i in range(n):
            dp[i][1] = (prefix_sum[i + 1] + k) * sum(cost[:i + 1])

        for j in range(2, k + 1):
            suffix_cost = [0] * (n + 1)
            suffix_cost[-1] = cost[-1]
            for i in range(n - 2, -1, -1):
                suffix_cost[i] = suffix_cost[i + 1] + cost[i]

            right_sum = 0
            for i in range(n - 1, -1, -1):
                right_sum += nums[i]
                dp[i][j] = min(dp[i][j], (right_sum + k * j) * suffix_cost[i])
                if i > 0:
                    dp[i - 1][j] = min(dp[i - 1][j], dp[i][j] + (prefix_sum[i + 1] - prefix_sum[i]) * cost[i])

        return min(dp[i][k] for i in range(n))
```
